package com.bookeat.payment.service;
import com.bookeat.payment.entity.*;import com.bookeat.payment.enums.*;import com.bookeat.payment.repository.*;import com.bookeat.payment.dto.*;import com.bookeat.payment.gateway.GatewayPort;import com.bookeat.commerce.service.*;import com.bookeat.common.audit.AuditService;import com.bookeat.exception.*;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.time.*;import java.math.*;
@Service @RequiredArgsConstructor @Transactional public class FinanceTransactions {
 private final PaymentRepository payments;private final RefundRepository refunds;private final SettlementRepository settlements;private final CommissionRuleRepository rules;private final PaymentTransactions paymentTx;private final CommerceAccess access;private final IdempotencyService idempotency;private final AuditService audit;private final JdbcTemplate jdbc;private final Clock clock;private final List<PaymentWalletPort> wallets;private final List<RefundObserver> refundObservers;
 public UUID request(UUID actor,String key,PaymentRequests.RefundRequest q){return idempotency.execute(actor,"refund-request",key,q,()->{var p=paymentTx.lock(q.paymentId());if(p.getGateway()!=PaymentGateway.CASH&&p.getGateway()!=PaymentGateway.WALLET)paymentTx.requireGatewayContext(p);if(!p.getCustomerId().equals(access.customer(actor)))throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);if(p.getSettlementId()!=null||!Set.of(PaymentStatus.SUCCESS,PaymentStatus.PARTIALLY_REFUNDED).contains(p.getStatus()))throw new ApiException(ErrorCode.REFUND_INVALID);BigDecimal reserved=refunds.findByPaymentId(p.getId()).stream().filter(r->r.getStatus()!=RefundStatus.REJECTED&&r.getStatus()!=RefundStatus.FAILED).map(Refund::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);if(!PaymentRules.refundAllowed(p.getAmount(),reserved,q.amount()))throw new ApiException(ErrorCode.REFUND_INVALID);var r=new Refund();r.setPaymentId(p.getId());r.setAmount(q.amount());r.setReason(q.reason());r.setStatus(RefundStatus.REQUESTED);r.setRequestedBy(actor);r.setRequestedAt(clock.instant());refunds.saveAndFlush(r);audit.record(actor,"REFUND_REQUESTED","Refund",r.getId(),null);return r.getId();});}
 public Refund decide(UUID actor,UUID id,PaymentRequests.Action q,boolean approve){var r=lockRefund(id);access.version(r.getVersion(),q.version());if(r.getStatus()!=RefundStatus.REQUESTED)throw new ApiException(ErrorCode.REFUND_INVALID);if(approve&&r.getRequestedBy().equals(actor))throw new ApiException(ErrorCode.ACCESS_DENIED);if(payments.findById(r.getPaymentId()).orElseThrow().getSettlementId()!=null)throw new ApiException(ErrorCode.REFUND_INVALID);r.setStatus(approve?RefundStatus.APPROVED:RefundStatus.REJECTED);r.setApprovedBy(actor);audit.recordReason(actor,approve?"REFUND_APPROVED":"REFUND_REJECTED","Refund",id,q.reason());refunds.flush();return r;}
 public boolean dispatch(UUID actor,UUID id){var r=lockRefund(id);if(r.getStatus()!=RefundStatus.APPROVED||r.getDispatchStartedAt()!=null)return false;var p=payments.findById(r.getPaymentId()).orElseThrow();if(p.getGateway()!=PaymentGateway.CASH&&p.getGateway()!=PaymentGateway.WALLET)paymentTx.requireGatewayContext(p);if(p.getSettlementId()!=null)throw new ApiException(ErrorCode.REFUND_INVALID);r.setStatus(RefundStatus.PROCESSING);r.setDispatchStartedAt(clock.instant());if(p.getGateway()==PaymentGateway.WALLET){if(wallets.isEmpty())throw new ApiException(ErrorCode.PAYMENT_GATEWAY_UNAVAILABLE);for(var w:wallets)w.refund(p.getCustomerId(),r.getId(),r.getAmount(),actor);complete(r,p,actor,null);}refunds.flush();return p.getGateway()==PaymentGateway.RAZORPAY;}
 public void attachRefund(UUID actor,UUID id,GatewayPort.GatewayRefund proof){var r=lockRefund(id);var p=payments.findById(r.getPaymentId()).orElseThrow();paymentTx.requireGatewayContext(p);if(p.getGateway()!=PaymentGateway.RAZORPAY||!Objects.equals(proof.paymentId(),p.getGatewayPaymentId())||proof.amount()!=PaymentRules.minor(r.getAmount())||!r.getId().toString().equals(proof.receipt())||!com.bookeat.payment.gateway.RazorpayPaymentsGateway.validId(proof.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);if(r.getGatewayRefundId()!=null&&!r.getGatewayRefundId().equals(proof.id()))throw new ApiException(ErrorCode.PAYMENT_INVALID);if(r.getStatus()==RefundStatus.REFUNDED)return;if(r.getStatus()!=RefundStatus.PROCESSING)throw new ApiException(ErrorCode.REFUND_INVALID);r.setGatewayRefundId(proof.id());if("processed".equals(proof.status()))complete(r,p,actor,proof.id());else if("failed".equals(proof.status())){r.setStatus(RefundStatus.FAILED);r.setFailureReason("Provider confirmed failure");}refunds.flush();}
 public Refund cashRefund(UUID actor,UUID rid,UUID id,PaymentRequests.Action q,String receipt){UUID actual=jdbc.query("select p.restaurant_id from refunds r join payments p on p.id=r.payment_id where r.id=?",(row,n)->row.getObject(1,UUID.class),id).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));if(!actual.equals(rid))throw new ApiException(ErrorCode.RESOURCE_NOT_FOUND);access.lockOwner(actor,rid);var r=lockRefund(id);var p=payments.findById(r.getPaymentId()).orElseThrow();access.lockOwner(actor,rid);if(!p.getRestaurantId().equals(rid)||p.getGateway()!=PaymentGateway.CASH||r.getStatus()!=RefundStatus.PROCESSING||receipt==null||!receipt.matches("[A-Za-z0-9_-]{8,80}"))throw new ApiException(ErrorCode.REFUND_INVALID);access.version(r.getVersion(),q.version());complete(r,p,actor,"cash_"+receipt);return r;}
 private void complete(Refund r,Payment p,UUID actor,String proof){if(r.getStatus()==RefundStatus.REFUNDED)return;if(p.getRefundedAmount().add(r.getAmount()).compareTo(p.getAmount())>0)throw new ApiException(ErrorCode.REFUND_INVALID);r.setGatewayRefundId(proof);r.setStatus(RefundStatus.REFUNDED);r.setProcessedAt(clock.instant());p.setRefundedAmount(p.getRefundedAmount().add(r.getAmount()));p.setStatus(p.getRefundedAmount().compareTo(p.getAmount())==0?PaymentStatus.REFUNDED:PaymentStatus.PARTIALLY_REFUNDED);for(var observer:refundObservers)observer.completed(p,r,actor);audit.record(actor,"REFUND_COMPLETED","Refund",r.getId(),null);refunds.flush();}
 public Refund lockRefund(UUID id){UUID payment=jdbc.query("select payment_id from refunds where id=?",(r,n)->r.getObject(1,UUID.class),id).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));paymentTx.lock(payment);return refunds.findById(id).orElseThrow();}
 public CommissionRule commission(UUID actor,PaymentRequests.Commission q){if(q.effectiveUntil()!=null&&!q.effectiveUntil().isAfter(q.effectiveFrom()))throw new ApiException(ErrorCode.VALIDATION_FAILED);if(q.commissionType()==CommissionType.PERCENTAGE&&q.commissionValue().compareTo(BigDecimal.valueOf(100))>0)throw new ApiException(ErrorCode.VALIDATION_FAILED);var r=new CommissionRule();r.setServiceType(q.serviceType().name());r.setCommissionType(q.commissionType());r.setCommissionValue(q.commissionValue());r.setEffectiveFrom(q.effectiveFrom());r.setEffectiveUntil(q.effectiveUntil());r.setActive(q.active());rules.saveAndFlush(r);audit.record(actor,"COMMISSION_RULE_CREATED","CommissionRule",r.getId(),null);return r;}
 public CommissionRule disableCommission(UUID actor,UUID id,PaymentRequests.Action q){var r=rules.findById(id).orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.version(r.getVersion(),q.version());r.setActive(false);rules.flush();audit.record(actor,"COMMISSION_RULE_DISABLED","CommissionRule",id,null);return r;}
 public UUID settlement(UUID actor,String key,PaymentRequests.SettlementCreate q){return idempotency.execute(actor,"settlement-create",key,q,()->{access.lock(q.restaurantId());if(!q.periodEnd().isAfter(q.periodStart())||q.periodEnd().isAfter(clock.instant())||Duration.between(q.periodStart(),q.periodEnd()).toDays()>366)throw new ApiException(ErrorCode.VALIDATION_FAILED);var ids=jdbc.query("select p.id from payments p where p.restaurant_id=? and p.verified_at>=? and p.verified_at<? and p.status in ('SUCCESS','PARTIALLY_REFUNDED','REFUNDED') and p.gateway<>'CASH' and p.settlement_id is null and not exists(select 1 from refunds r where r.payment_id=p.id and r.status in ('REQUESTED','APPROVED','PROCESSING')) order by p.id",(r,n)->r.getObject(1,UUID.class),q.restaurantId(),java.sql.Timestamp.from(q.periodStart()),java.sql.Timestamp.from(q.periodEnd()));if(ids.isEmpty())throw new ApiException(ErrorCode.PAYMENT_NOT_DUE);var list=payments.findAllById(ids);var s=new Settlement();s.setRestaurantId(q.restaurantId());s.setPeriodStart(q.periodStart());s.setPeriodEnd(q.periodEnd());s.setGrossAmount(sum(list,Payment::getAmount));s.setRefundAmount(sum(list,Payment::getRefundedAmount));s.setGatewayFee(sum(list,Payment::getGatewayFee));s.setTaxAmount(sum(list,Payment::getGatewayTax));s.setCommissionAmount(list.stream().map(p->p.getCommissionAmount().multiply(p.getAmount().subtract(p.getRefundedAmount())).divide(p.getAmount(),2,RoundingMode.HALF_UP)).reduce(BigDecimal.ZERO,BigDecimal::add));s.setNetAmount(s.getGrossAmount().subtract(s.getRefundAmount()).subtract(s.getCommissionAmount()).subtract(s.getGatewayFee()).subtract(s.getTaxAmount()));s.setStatus(s.getNetAmount().signum()<0?SettlementStatus.ON_HOLD:SettlementStatus.PENDING);settlements.saveAndFlush(s);list.forEach(p->p.setSettlementId(s.getId()));payments.flush();audit.record(actor,"SETTLEMENT_CREATED","Settlement",s.getId(),null);return s.getId();});}
 private BigDecimal sum(List<Payment> list,java.util.function.Function<Payment,BigDecimal> field){return list.stream().map(field).reduce(BigDecimal.ZERO,BigDecimal::add);}
 public Settlement settlementAction(UUID actor,UUID id,PaymentRequests.SettlementAction q){UUID rid=jdbc.query("select restaurant_id from settlements where id=?",(r,n)->r.getObject(1,UUID.class),id).stream().findFirst().orElseThrow(()->new ApiException(ErrorCode.RESOURCE_NOT_FOUND));access.lock(rid);var s=settlements.findById(id).orElseThrow();access.version(s.getVersion(),q.version());if(s.getStatus()==SettlementStatus.COMPLETED)throw new ApiException(ErrorCode.CONFLICT);boolean valid=switch(q.status()){case PROCESSING->s.getStatus()==SettlementStatus.PENDING||s.getStatus()==SettlementStatus.FAILED;case COMPLETED->s.getStatus()==SettlementStatus.PROCESSING;case FAILED->s.getStatus()==SettlementStatus.PROCESSING;case ON_HOLD->true;case PENDING->s.getStatus()==SettlementStatus.ON_HOLD;};if(!valid||s.getNetAmount().signum()<0&&q.status()!=SettlementStatus.ON_HOLD)throw new ApiException(ErrorCode.CONFLICT);if(q.status()==SettlementStatus.COMPLETED){if(q.settlementReference()==null||!q.settlementReference().matches("[A-Za-z0-9_-]{8,100}"))throw new ApiException(ErrorCode.VALIDATION_FAILED);s.setSettlementReference(q.settlementReference());s.setProcessedAt(clock.instant());}s.setStatus(q.status());settlements.flush();audit.recordReason(actor,"SETTLEMENT_"+q.status(),"Settlement",id,q.reason());return s;}
}
